import React, { useEffect } from 'react';

const ImageViewer = ({ content, closeModal, setCurrentContent }) => {
  const { text, images, carousel, currentImageIndex } = content;

  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'Escape') {
        closeModal();
      } else if (e.key === 'ArrowLeft' && carousel && currentImageIndex > 0) {
        handlePrevSlide();
      } else if (e.key === 'ArrowRight' && carousel && currentImageIndex < images.length - 1) {
        handleNextSlide();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    // Prevent scrolling when modal is open
    document.body.style.overflow = 'hidden';

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'auto';
    };
  }, [closeModal, carousel, currentImageIndex, images]);

  const handleNextSlide = () => {
    if (currentImageIndex < images.length - 1) {
      setCurrentContent({
        ...content,
        currentImageIndex: currentImageIndex + 1
      });
    }
  };

  const handlePrevSlide = () => {
    if (currentImageIndex > 0) {
      setCurrentContent({
        ...content,
        currentImageIndex: currentImageIndex - 1
      });
    }
  };

  // Ensure images exist and is an array
  const validImages = Array.isArray(images) ? images : [];

  return (
    <div className="modal-overlay" onClick={closeModal}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        {validImages.length > 0 && (
          <div className="image-container">
            {carousel && validImages.length > 1 ? (
              <>
                <img 
                  className="modal-image" 
                  src={validImages[currentImageIndex]} 
                  alt={`Slide ${currentImageIndex + 1}`} 
                />
                <div className="carousel-controls">
                  {currentImageIndex > 0 && (
                    <button 
                      className="prev-btn" 
                      onClick={handlePrevSlide}
                    >
                      &#10094;
                    </button>
                  )}
                  {currentImageIndex < validImages.length - 1 && (
                    <button 
                      className="next-btn" 
                      onClick={handleNextSlide}
                    >
                      &#10095;
                    </button>
                  )}
                </div>
              </>
            ) : (
              <img 
                className="modal-image" 
                src={validImages[0]} 
                alt="Modal" 
              />
            )}
          </div>
        )}

        {text && (
          <div 
            className="modal-caption" 
            dangerouslySetInnerHTML={{ __html: text }}
          />
        )}

        <button 
          className="close-btn" 
          onClick={closeModal}
        >
          &times;
        </button>
      </div>
    </div>
  );
};

export default ImageViewer;
